/* FRAME/12 Design System — Tokens, Panel Grammar, Screentone, and Motion on Twos.
   Works standalone without Tailwind. */

:root {
  --f-desk: #e2e3e5;
  --f-sheet: #ffffff;
  --f-panel: #ffffff;
  --f-ink: #121212;
  --f-ink-2: #4b4b4b;
  --f-rule: #121212;
  --f-tone: #121212;
  --f-grid: #e3e3e3;
  --f-marker: #ffd60a;
  --f-marker-ink: #121212;
  --f-hole: #e2e3e5;

  --f-gutter-pair: 12px;
  --f-gutter-scene: 20px;
  --f-gutter-change: 32px;

  --font-f-display: "Dela Gothic One", "Arial Black", "Helvetica Neue", sans-serif;
  --font-f-body: "Zen Kaku Gothic New", "Hiragino Sans", "Helvetica Neue", Arial, sans-serif;
  --font-f-mono: "M PLUS 1 Code", ui-monospace, "SF Mono", Menlo, monospace;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --f-desk: #000000;
    --f-sheet: #050505;
    --f-panel: #19191a;
    --f-ink: #f1f0ea;
    --f-ink-2: #b9b8b1;
    --f-rule: #f1f0ea;
    --f-tone: #f1f0ea;
    --f-grid: #2c2c2d;
    --f-marker: #ffd60a;
    --f-marker-ink: #121212;
    --f-hole: #000000;
    color-scheme: dark;
  }
}

:root[data-theme="dark"] {
  --f-desk: #000000;
  --f-sheet: #050505;
  --f-panel: #19191a;
  --f-ink: #f1f0ea;
  --f-ink-2: #b9b8b1;
  --f-rule: #f1f0ea;
  --f-tone: #f1f0ea;
  --f-grid: #2c2c2d;
  --f-marker: #ffd60a;
  --f-marker-ink: #121212;
  --f-hole: #000000;
  color-scheme: dark;
}

.theme-light {
  --f-desk: #e2e3e5;
  --f-sheet: #ffffff;
  --f-panel: #ffffff;
  --f-ink: #121212;
  --f-ink-2: #4b4b4b;
  --f-rule: #121212;
  --f-tone: #121212;
  --f-grid: #e3e3e3;
  --f-marker: #ffd60a;
  --f-marker-ink: #121212;
  --f-hole: #e2e3e5;
  color-scheme: light;
}

.theme-dark {
  --f-desk: #000000;
  --f-sheet: #050505;
  --f-panel: #19191a;
  --f-ink: #f1f0ea;
  --f-ink-2: #b9b8b1;
  --f-rule: #f1f0ea;
  --f-tone: #f1f0ea;
  --f-grid: #2c2c2d;
  --f-marker: #ffd60a;
  --f-marker-ink: #121212;
  --f-hole: #000000;
  color-scheme: dark;
}

/* ===================================================================== Base & Reset */
.dash,
.sheet,
.scene,
.panel,
.pair,
.rng,
.metric,
.chart,
.ints,
.f12-btn,
.f12-field,
.f12-input,
.f12-dialog,
.f12-select,
.f12-tooltip-wrap,
.f12-menu-wrap,
.f12-table-wrap {
  box-sizing: border-box;
}
.dash *,
.dash *::before,
.dash *::after,
.sheet *,
.sheet *::before,
.sheet *::after,
.panel *,
.panel *::before,
.panel *::after,
.f12-dialog *,
.f12-select *,
.f12-table-wrap * {
  box-sizing: border-box;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

button {
  font: inherit;
  color: inherit;
}

:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}

/* ===================================================================== Sheet & Pegs */
.dash {
  container-type: inline-size;
  position: relative;
}
.dash h2,
.dash h3,
.dash p,
.dash ul {
  margin: 0;
}
.dash ul {
  list-style: none;
  padding: 0;
}

.frame {
  background: var(--f-desk);
  color: var(--f-ink);
  font-family: var(--font-f-body);
  padding: 20px;
  border-radius: 4px;
}

.sheet,
.frame .sheet {
  position: relative;
  background: var(--f-sheet);
  color: var(--f-ink);
  font-family: var(--font-f-body);
  padding: 44px 28px 28px;
  display: flex;
  flex-direction: column;
  gap: 32px; /* 32 = scene change */
  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.05), 0 18px 40px -26px rgba(0, 0, 0, 0.5);
}

.pegs,
.frame .pegs {
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 26px;
  align-items: center;
}
.peg,
.frame .peg {
  display: block;
  background: var(--f-hole);
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.25);
}
.peg.round,
.frame .peg.round {
  width: 11px;
  height: 11px;
  border-radius: 50%;
}
.peg.slot,
.frame .peg.slot {
  width: 26px;
  height: 8px;
  border-radius: 4px;
}

.hd,
.frame .hd {
  display: flex;
  flex-wrap: wrap;
  gap: 16px 24px;
  align-items: flex-end;
  justify-content: space-between;
}
.eyebrow,
.frame .eyebrow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  font-family: var(--font-f-mono);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--f-ink-2);
}
.title,
.frame .title {
  font-family: var(--font-f-display);
  font-weight: 400;
  font-size: clamp(30px, 5.2cqi, 46px);
  line-height: 1.02;
  margin-top: 10px;
  letter-spacing: 0.005em;
  text-wrap: balance;
}
.sub,
.frame .sub {
  font-family: var(--font-f-mono);
  font-size: 12px;
  color: var(--f-ink-2);
  margin-top: 8px;
  letter-spacing: 0.04em;
}

/* ===================================================================== Scene & Gutter Grammar
   12px = pair, 20px = same scene, 32px = scene change */
.scene,
.frame .scene {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);
  gap: 20px;
  min-width: 0;
}
.scene.scene-split,
.frame .scene.scene-split {
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);
}
.scene.scene-stack,
.frame .scene.scene-stack {
  grid-template-columns: minmax(0, 1fr);
}
.scene.scene-equal,
.frame .scene.scene-equal {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.scene.scene-three,
.frame .scene.scene-three {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.scene.scene-pair,
.frame .scene.scene-pair {
  gap: 12px;
}
.scene.scene-scene,
.frame .scene.scene-scene {
  gap: 20px;
}
.scene.scene-change,
.frame .scene.scene-change {
  gap: 32px;
}

.pair,
.frame .pair {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
}
.pair > .panel,
.frame .pair .panel {
  flex: 1;
}

/* ===================================================================== Panel */
.panel,
.frame .panel {
  position: relative;
  min-width: 0;
  display: flex;
  flex-direction: column;
  color: var(--f-ink);
  font-family: var(--font-f-body);
}
.panel-frame,
.frame .panel-frame {
  position: absolute;
  inset: 0;
  overflow: visible;
  pointer-events: none;
}
.panel-frame polygon,
.frame .panel-frame polygon {
  fill: var(--f-panel);
  stroke: var(--f-rule);
  stroke-width: 2.5;
  stroke-linejoin: miter;
}
.panel-body,
.frame .panel-body {
  flex: 1;
  display: flex;
  flex-direction: column;
  position: relative;
  padding: 24px 22px 22px;
}
.panel.slant-bottom .panel-body,
.frame .panel.slant-bottom .panel-body {
  padding-bottom: 36px;
}
.panel.slant-top .panel-body,
.frame .panel.slant-top .panel-body {
  padding-top: 36px;
}
.cut,
.frame .cut {
  position: absolute;
  top: -8px;
  left: 16px;
  z-index: 1;
  padding: 0 6px;
  line-height: 16px;
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.12em;
  background: var(--f-sheet);
  color: var(--f-ink);
}
.panel.slant-top .cut,
.frame .panel.slant-top .cut {
  top: 8px;
}

/* ===================================================================== Tag & Badge */
.tag,
.frame .tag {
  display: inline-block;
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-marker-ink);
  background: var(--f-marker);
  padding: 1px 6px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.badge,
.frame .badge {
  position: relative;
  display: inline-flex;
  align-items: center;
  white-space: nowrap;
  font-family: var(--font-f-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 2px 7px;
  background: var(--f-marker);
  color: var(--f-marker-ink);
  border: 2px solid var(--f-rule);
}
.badge-t {
  position: relative;
  z-index: 1;
}
.burst {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 150%;
  height: auto;
  transform: translate(-50%, -50%);
  opacity: 0;
  pointer-events: none;
}
.burst line,
.frame .burst line {
  stroke: var(--f-ink);
  stroke-width: 2;
  stroke-linecap: square;
}

/* ===================================================================== SegmentedControl (RangeTabs) */
.rng,
.frame .rng {
  position: relative;
  display: inline-flex;
  flex: none;
  isolation: isolate;
  border: 2.5px solid var(--f-rule);
  background: var(--f-panel);
}
.rng-ind,
.frame .rng-ind {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  z-index: 1;
  background: #ffffff;
  mix-blend-mode: difference;
  pointer-events: none;
}
.rng-btn,
.frame .rng-btn {
  cursor: pointer;
  background: none;
  border: 0;
  display: grid;
  justify-items: center;
  padding: 6px 16px 5px;
  color: var(--f-ink);
  min-width: 64px;
}
.rng-btn + .rng-btn,
.frame .rng-btn + .rng-btn {
  border-left: 2px solid var(--f-rule);
}
.rng-n,
.frame .rng-n {
  font-family: var(--font-f-display);
  font-size: 18px;
  line-height: 1;
}
.rng-u,
.frame .rng-u {
  font-family: var(--font-f-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.rng-btn:focus-visible,
.frame .rng-btn:focus-visible {
  outline: 3px solid var(--f-marker);
  outline-offset: -6px;
}

/* ===================================================================== Button & Input */
.f12-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  cursor: pointer;
  font-family: var(--font-f-mono);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border: 2.5px solid var(--f-rule);
  background: var(--f-panel);
  color: var(--f-ink);
  padding: 8px 16px;
  font-size: 12px;
  line-height: 1.2;
}
.f12-btn-sm {
  padding: 5px 10px;
  font-size: 11px;
}
.f12-btn-md {
  padding: 8px 16px;
  font-size: 12px;
}
.f12-btn-lg {
  padding: 12px 22px;
  font-size: 13px;
}
.f12-btn-primary {
  background: var(--f-ink);
  color: var(--f-panel);
}
.f12-btn-secondary {
  background: var(--f-panel);
  color: var(--f-ink);
}
.f12-btn-marker {
  background: var(--f-marker);
  color: var(--f-marker-ink);
}
.f12-btn:hover:not(:disabled) {
  box-shadow: 3px 3px 0 var(--f-rule);
}
.f12-btn:active:not(:disabled) {
  box-shadow: none;
}
.f12-btn:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-btn:disabled {
  cursor: not-allowed;
  border-style: dashed;
  color: var(--f-ink-2);
  background: var(--f-panel);
}

.f12-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-family: var(--font-f-body);
  color: var(--f-ink);
}
.f12-label {
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
}
.f12-input {
  width: 100%;
  padding: 9px 12px;
  font-family: var(--font-f-body);
  font-size: 14px;
  line-height: 1.4;
  color: var(--f-ink);
  background: var(--f-panel);
  border: 2.5px solid var(--f-rule);
  border-radius: 0;
}
.f12-input::placeholder {
  color: var(--f-ink-2);
}
.f12-input:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 2px;
}
.f12-hint {
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-ink-2);
  margin: 0;
}
.f12-error {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-f-mono);
  font-size: 11px;
  color: var(--f-ink);
  margin: 0;
}
.f12-error-flag {
  background: var(--f-marker);
  color: var(--f-marker-ink);
  padding: 0 4px;
  font-weight: 700;
}

/* ===================================================================== Metric, Delta & Spark */
.metric {
  display: flex;
  flex-direction: column;
  flex: 1;
}
.m-label,
.frame .m-label {
  font-family: var(--font-f-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
  margin: 0;
}
.m-value,
.frame .m-value {
  font-family: var(--font-f-display);
  font-weight: 400;
  font-size: 34px;
  line-height: 1.05;
  margin: 10px 0 0;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.01em;
  color: var(--f-ink);
}
.metric.big .m-value,
.frame .metric.big .m-value {
  font-size: clamp(36px, 6cqi, 56px);
}
.delta,
.frame .delta {
  display: flex;
  align-items: baseline;
  gap: 6px;
  flex-wrap: wrap;
  font-variant-numeric: tabular-nums;
  font-family: var(--font-f-mono);
  font-size: 12px;
  margin: 10px 0 0;
  letter-spacing: 0.02em;
  color: var(--f-ink);
}
.delta-sym,
.frame .delta-sym {
  font-size: 10px;
}
.delta.up .delta-sym,
.delta.down .delta-sym,
.frame .delta.up .delta-sym,
.frame .delta.down .delta-sym {
  color: var(--f-marker-ink);
  background: var(--f-marker);
  padding: 0 3px;
}
.delta-ref,
.frame .delta-ref {
  color: var(--f-ink-2);
}
.m-note,
.frame .m-note {
  font-size: 13px;
  color: var(--f-ink-2);
  margin: 6px 0 0;
  max-width: 30ch;
}

.spark {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: auto;
  padding-top: 16px;
}
.spark svg,
.frame .spark svg {
  display: block;
  border-bottom: 2px solid var(--f-rule);
  overflow: visible;
}
.spark-l,
.frame .spark-l {
  font-family: var(--font-f-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--f-ink-2);
  margin: 0;
}
.spark-bar,
.frame .spark-bar {
  stroke: var(--f-ink);
  stroke-width: 1;
}

/* ===================================================================== Chart, Balloon & Data Table */
.c01-hd,
.frame .c01-hd {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: flex-end;
  gap: 12px 24px;
  margin-bottom: 4px;
}
.legend,
.legend-hint,
.frame .legend,
.frame .legend-hint {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 16px;
  font-family: var(--font-f-mono);
  font-size: 11px;
  letter-spacing: 0.04em;
  color: var(--f-ink-2);
  margin: 0;
  padding: 0;
  list-style: none;
}
.legend li {
  display: flex;
  align-items: center;
  gap: 6px;
}
.legend-hint,
.frame .legend-hint {
  max-width: 26ch;
}
.sw {
  display: inline-block;
  width: 14px;
  height: 0;
  border-top-width: 2px;
  border-top-style: solid;
  flex: none;
}
.sw-total,
.frame .sw-total {
  border-color: var(--f-ink);
  border-top-width: 2.5px;
}
.sw-focus,
.frame .sw-focus {
  border-color: var(--f-ink);
  border-top-style: dashed;
}

.chart {
  position: relative;
  width: 100%;
  touch-action: pan-y;
}
.chart-svg {
  display: block;
  overflow: visible;
}
.chart-svg:focus-visible {
  outline: 3px solid var(--f-ink);
  outline-offset: 4px;
}
.chart text,
.frame .chart text {
  fill: var(--f-ink-2);
  font-family: var(--font-f-mono);
  font-size: 10.5px;
  font-variant-numeric: tabular-nums;
}
.grid,
.frame .grid {
  stroke: var(--f-grid);
}
.baseline,
.frame .baseline {
  stroke: var(--f-rule);
  stroke-width: 2;
}
.sheet-ticks line,
.frame .sheet-ticks line {
  stroke: var(--f-rule);
  stroke-width: 1;
}
.tone-dot,
.frame .tone-dot {
  fill: var(--f-tone);
}
.l-total,
.frame .l-total {
  stroke: var(--f-ink);
  stroke-width: 2.5;
  stroke-linejoin: round;
  stroke-linecap: round;
}
.l-focus,
.frame .l-focus {
  stroke: var(--f-ink);
  stroke-width: 2;
  stroke-dasharray: 6 4;
  stroke-linejoin: round;
}
.tail,
.frame .tail {
  fill: var(--f-panel);
  stroke: var(--f-rule);
  stroke-width: 2;
  stroke-linejoin: miter;
}
.peak-dot,
.frame .peak-dot {
  fill: var(--f-marker);
  stroke: var(--f-rule);
  stroke-width: 2;
}
.balloon,
.frame .balloon {
  position: absolute;
  z-index: 2;
  white-space: nowrap;
  display: flex;
  align-items: center;
  padding: 0 12px;
  background: var(--f-panel);
  color: var(--f-ink);
  border: 2px solid var(--f-rule);
  border-radius: 14px;
  font-family: var(--font-f-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.02em;
  font-variant-numeric: tabular-nums;
}
.balloon-gap,
.frame .balloon-gap {
  position: absolute;
  bottom: -2px;
  width: 10px;
  height: 3px;
  background: var(--f-panel);
}
.balloon-standalone {
  position: relative;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
}
.balloon-standalone .balloon {
  position: relative;
  height: 28px;
}
.balloon-standalone-svg {
  display: block;
  overflow: visible;
  margin-top: -1px;
}

.cross line,
.frame .cross line {
  stroke: var(--f-ink);
  stroke-width: 1;
}
.cross-dot,
.frame .cross-dot {
  fill: var(--f-marker);
  stroke: var(--f-rule);
  stroke-width: 2;
}
.cross-dot2,
.frame .cross-dot2 {
  fill: var(--f-panel);
  stroke: var(--f-rule);
  stroke-width: 2;
}
.tip,
.frame .tip {
  position: absolute;
  z-index: 3;
  pointer-events: none;
  display: grid;
  gap: 2px;
  min-width: 160px;
  padding: 8px 10px;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  background: var(--f-panel);
  border: 2px solid var(--f-rule);
  color: var(--f-ink);
  font-family: var(--font-f-mono);
  box-shadow: 4px 4px 0 var(--f-rule);
}
.tip span {
  display: flex;
  align-items: center;
  gap: 6px;
}

.tbl,
.frame .tbl {
  margin-top: 10px;
  font-family: var(--font-f-mono);
  font-size: 12px;
  color: var(--f-ink);
}
.tbl summary,
.frame .tbl summary {
  cursor: pointer;
  width: max-content;
  padding: 4px 0;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.tbl-scroll {
  max-height: 240px;
  overflow: auto;
  margin-top: 6px;
}
.tbl table {
  border-collapse: collapse;
  width: 100%;
  font-variant-numeric: tabular-nums;
}
.tbl th,
.tbl td {
  text-align: left;
  padding: 5px 10px 5px 0;
  white-space: nowrap;
}
.tbl th,
.frame .tbl th {
  color: var(--f-ink-2);
