/* ===================================================================== Responsive Container Rules */
@container (max-width: 760px) {
  .frame {
    padding: 6px;
  }
  .sheet,
  .frame .sheet {
    padding: 40px 14px 18px;
    gap: 24px;
  }
  .scene,
  .frame .scene,
  .scene.scene-split,
  .scene.scene-equal,
  .scene.scene-three {
    grid-template-columns: minmax(0, 1fr);
  }
  .panel-body,
  .frame .panel-body {
    padding: 22px 14px 18px;
  }
  .int-row,
  .frame .int-row {
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas: "name val" "bar bar";
    gap: 8px 12px;
  }
  .int-name,
  .frame .int-name {
    grid-area: name;
  }
  .int-val,
  .frame .int-val {
    grid-area: val;
  }
  .int-bar,
