  }
}

/* ===================================================================== Motion Grammar
   smooth  = continuous easing
   stepped = poses held on twos: 12 drawings/s, each pose 83.33ms
   cut     = instant, editorial hard cut */
.m-smooth .rng-ind {
  transition: transform 260ms cubic-bezier(0.2, 0.8, 0.2, 1), width 260ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.m-stepped .rng-ind {
  transition: transform 250ms steps(3, end), width 250ms steps(3, end);
}
.m-smooth .rng-btn {
  transition: color 180ms ease 60ms;
}
.m-stepped .rng-btn {
  transition: color 0ms linear 166ms;
}

.m-smooth .enter {
  animation: enterSmooth 260ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
@keyframes enterSmooth {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.m-stepped .enter {
  animation: enterStep 250ms;
  animation-timing-function: step-end;
}
@keyframes enterStep {
  0% {
    opacity: 0.35;
    transform: translateY(10px);
  }
  33% {
    opacity: 0.8;
    transform: translateY(4px);
  }
  66% {
    opacity: 1;
    transform: translateY(1px);
  }
  100% {
    opacity: 1;
    transform: none;
  }
}

.m-smooth .pop {
  animation: popSmooth 240ms cubic-bezier(0.2, 0.9, 0.3, 1.25);
}
@keyframes popSmooth {
  from {
    opacity: 0;
    transform: scale(0.85);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.m-stepped .pop {
  animation: popStep 333ms;
  animation-timing-function: step-end;
}
@keyframes popStep {
  0% {
    transform: scale(0.5);
  }
  25% {
    transform: scale(1.22);
  }
  50% {
    transform: scale(0.94);
  }
  75% {
    transform: scale(1);
  }
  100% {
    transform: none;
  }
}
.m-stepped .pop .burst {
  animation: burstStep 250ms;
  animation-timing-function: step-end;
}
@keyframes burstStep {
  0% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(0.85);
  }
  33% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1.08);
  }
  66%,
  100% {
    opacity: 0;
  }
}
.m-smooth .pop .burst {
  animation: burstSmooth 320ms ease-out;
}
@keyframes burstSmooth {
  from {
    opacity: 0.9;
    transform: translate(-50%, -50%) scale(0.85);
  }
  to {
    opacity: 0;
    transform: translate(-50%, -50%) scale(1.15);
  }
}

@media (prefers-reduced-motion: reduce) {
  .dash *,
  .dash *::before,
  .dash *::after,
  .sheet *,
  .sheet *::before,
  .sheet *::after {
    animation: none !important;
    transition: none !important;
  }
}

/* Optional Tailwind v4 @theme mapping for FRAME/12 tokens and gutter grammar.
   Import alongside frame12.css when using Tailwind CSS v4. */

@import "./frame12.css";

@theme inline {
  --color-f-desk: var(--f-desk);
  --color-f-sheet: var(--f-sheet);
  --color-f-panel: var(--f-panel);
  --color-f-ink: var(--f-ink);
  --color-f-ink-2: var(--f-ink-2);
  --color-f-rule: var(--f-rule);
  --color-f-tone: var(--f-tone);
  --color-f-grid: var(--f-grid);
  --color-f-marker: var(--f-marker);
  --color-f-marker-ink: var(--f-marker-ink);
  --color-f-hole: var(--f-hole);

  --font-f-display: var(--font-f-display);
  --font-f-body: var(--font-f-body);
  --font-f-mono: var(--font-f-mono);

  --spacing-gutter-pair: 12px;
  --spacing-gutter-scene: 20px;
  --spacing-gutter-change: 32px;
}

'use client';

import * as React from 'react';

export type MotionMode = 'stepped' | 'smooth' | 'cut';

export const FRAME_MS = 1000 / 12; // animating "on twos": 12 drawings per second (83.33ms per pose)

const easeOut = (t: number): number => 1 - Math.pow(1 - t, 3);

const useIsoLayoutEffect = typeof window !== 'undefined' ? React.useLayoutEffect : React.useEffect;

export function useSize(ref: { readonly current: HTMLElement | null }): { w: number; h: number } {
  const [size, setSize] = React.useState<{ w: number; h: number }>({ w: 0, h: 0 });

  useIsoLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    // Layout size (offsetWidth/Height), not the transformed box, so scaled previews draw correctly.
    const measure = () => {
      const w = el.offsetWidth;
      const h = el.offsetHeight;
      setSize((s) => (s.w === w && s.h === h ? s : { w, h }));
    };
    measure();
    if (typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, [ref]);

  return size;
}

export function useReducedMotion(): boolean {
  const [reduced, setReduced] = React.useState<boolean>(() => {
    if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return false;
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  });

  React.useEffect(() => {
    if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return;
    const q = window.matchMedia('(prefers-reduced-motion: reduce)');
    setReduced(q.matches);
    const on = () => setReduced(q.matches);
    if (q.addEventListener) {
      q.addEventListener('change', on);
      return () => q.removeEventListener('change', on);
    }
    q.addListener(on);
    return () => q.removeListener(on);
  }, []);

  return reduced;
}

/**
 * Progress 0..1 that replays whenever `key` changes.
 * Stepped mode samples the easing curve at 12 poses per second (83.33ms per pose),
 * like an animation spacing chart. Honors `prefers-reduced-motion: reduce`.
 */
export function useOnTwos(
  key: unknown,
  duration = 600,
  motion: MotionMode = 'stepped',
): number {
  const reduced = useReducedMotion();
  const effectiveMotion: MotionMode = reduced ? 'cut' : motion;
  const [p, setP] = React.useState<number>(1);
  const first = React.useRef<boolean>(true);

  useIsoLayoutEffect(() => {
    if (first.current) {
      first.current = false;
      return;
    }
    if (effectiveMotion === 'cut') {
      setP(1);
      return;
    }
    const start = performance.now();
    const frames = Math.max(2, Math.round(duration / FRAME_MS));
    let raf = 0;
    let last = -1;
    const tick = (now: number) => {
      const el = now - start;
      let t: number;
      if (effectiveMotion === 'stepped') {
        const k = Math.min(frames, Math.floor(el / FRAME_MS) + 1);
        t = k / frames;
      } else {
        t = Math.min(1, el / duration);
      }
      const v = easeOut(t);
      if (v !== last) {
        last = v;
        setP(v);
      }
      if (t < 1) raf = requestAnimationFrame(tick);
    };
    setP(effectiveMotion === 'stepped' ? easeOut(1 / frames) : 0);
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [key, duration, effectiveMotion]);

  return p;
}

export const useTween = useOnTwos;

export function useCountUp(
  value: number,
  motion: MotionMode = 'stepped',
  duration = 600,
): number {
  const prev = React.useRef<number>(value);
  const from = React.useRef<number>(value);
  if (prev.current !== value) {
    from.current = prev.current;
    prev.current = value;
  }
  const p = useOnTwos(value, duration, motion);
  return from.current + (value - from.current) * p;
}

/**
 * Becomes true after the first change of `key`, so entrance animations
 * never run on first paint (the page is complete at rest).
 */
export function useChanged(key: unknown): boolean {
  const first = React.useRef<unknown>(key);
  const [changed, setChanged] = React.useState<boolean>(false);
  React.useEffect(() => {
    if (key !== first.current) setChanged(true);
  }, [key]);
  return changed;
}

'use client';

import * as React from 'react';
import { type MotionMode, useReducedMotion } from '@/hooks/use-on-twos';

export interface SheetProps extends React.HTMLAttributes<HTMLDivElement> {
  pegs?: boolean;
  motion?: MotionMode;
  theme?: 'light' | 'dark';
  sheetClassName?: string;
  children?: React.ReactNode;
}

export function Pegs() {
  return (
    <div className="pegs" aria-hidden="true">
      <span className="peg slot" />
      <span className="peg round" />
      <span className="peg slot" />
    </div>
  );
}

export function Sheet({
  pegs = true,
  motion = 'stepped',
  theme,
  className = '',
  sheetClassName = '',
  children,
  ...rest
}: SheetProps) {
  const reduced = useReducedMotion();
  const effectiveMotion: MotionMode = reduced ? 'cut' : motion;
  const themeClass = theme ? ` theme-${theme}` : '';
  const outerClass = `dash frame m-${effectiveMotion}${themeClass}${className ? ` ${className}` : ''}`;
  const innerClass = `sheet${sheetClassName ? ` ${sheetClassName}` : ''}`;

  return (
    <div className={outerClass} data-theme={theme} {...rest}>
      <div className={innerClass}>
        {pegs && <Pegs />}
        {children}
      </div>
    </div>
  );
}

'use client';

import * as React from 'react';

export type SceneGutter = 'pair' | 'scene' | 'change';
export type SceneLayout = 'split' | 'stack' | 'equal' | 'three';

export const GUTTERS: Record<SceneGutter, number> = {
  pair: 12,
  scene: 20,
  change: 32,
};

export interface SceneProps extends React.HTMLAttributes<HTMLDivElement> {
  gutter?: SceneGutter;
  layout?: SceneLayout;
  children?: React.ReactNode;
}

export function Scene({
  gutter = 'scene',
  layout = 'split',
  className = '',
  children,
  ...rest
}: SceneProps) {
  const safeGutter: SceneGutter =
    gutter === 'pair' || gutter === 'scene' || gutter === 'change' ? gutter : 'scene';
  const safeLayout: SceneLayout =
    layout === 'split' || layout === 'stack' || layout === 'equal' || layout === 'three'
      ? layout
      : 'split';

  const classes = `scene scene-${safeLayout} scene-${safeGutter}${className ? ` ${className}` : ''}`;

  return (
    <div className={classes} data-gutter={GUTTERS[safeGutter]} data-layout={safeLayout} {...rest}>
      {children}
    </div>
  );
}

'use client';

import * as React from 'react';
import { useSize } from '@/hooks/use-on-twos';

export type PanelShape = 'rect' | 'slant-bottom' | 'slant-top';

export interface PanelProps extends React.HTMLAttributes<HTMLElement> {
  cut?: string;
  shape?: PanelShape;
  label?: string;
  children?: React.ReactNode;
}

export function Panel({
  cut,
  shape = 'rect',
  className = '',
  label,
  children,
  ...rest
}: PanelProps) {
  const ref = React.useRef<HTMLElement | null>(null);
  const { w, h } = useSize(ref);
  const s = 1.25; // half of 2.5px stroke
  const d = 16; // slant rise in px
  let pts: string;
  if (shape === 'slant-bottom') {
    pts = `${s},${s} ${w - s},${s} ${w - s},${h - s - d} ${s},${h - s}`;
  } else if (shape === 'slant-top') {
    pts = `${s},${s + d} ${w - s},${s} ${w - s},${h - s} ${s},${h - s}`;
  } else {
    pts = `${s},${s} ${w - s},${s} ${w - s},${h - s} ${s},${h - s}`;
  }

  return (
    <section
      ref={ref}
      className={`panel ${shape}${className ? ` ${className}` : ''}`}
      aria-label={label}
      {...rest}
    >
      {w > 0 && (
        <svg className="panel-frame" width={w} height={h} aria-hidden="true">
          <polygon points={pts} />
        </svg>
      )}
      {cut && (
        <span className="cut" aria-hidden="true">
          {cut}
        </span>
      )}
      <div className="panel-body">{children}</div>
    </section>
  );
}

